19	    /// However, the situation is different when one of the selectors has a higher specificity.
20	    /// In that case, source order does not matter: the selector with higher specificity will win out even if it comes first.
21	    ///
22	    /// The clashes of these two mechanisms for prioritization, source order and specificity, can cause some confusion when reading stylesheets.
23	    /// If a selector with higher specificity comes before the selector it overrides, we have to think harder to understand it, because it violates the source order expectation.
24	    /// **Stylesheets are most legible when overriding selectors always come after the selectors they override.**
25	    /// That way both mechanisms, source order and specificity, work together nicely.
26	    ///
27	    /// This rule enforces that practice as best it can, reporting fewer errors than it should.
28	    /// It cannot catch every actual overriding selector, but it can catch certain common mistakes.
29	    ///
30	    /// ## Examples
31	    ///
32	    /// ### Invalid
33	    ///
34	    /// ```css,expect_diagnostic
35	    /// b a { color: red; }
36	    /// a { color: red; }
37	    /// ```
38	    ///
39	    /// ```css,expect_diagnostic
40	    /// a {
41	    ///   & > b { color: red; }
42	    /// }
43	    /// b { color: red; }
44	    /// ```
45	    ///
46	    /// ```css,expect_diagnostic
47	    /// :root input {
48	    ///     color: red;
49	    /// }
50	    /// html input {
51	    ///     color: red;
52	    /// }
53	    /// ```
54	    ///
55	    ///
56	    /// ### Valid
57	    ///
58	    /// ```css
59	    /// a { color: red; }
60	    /// b a { color: red; }
61	    /// ```
62	    ///
63	    /// ```css
64	    /// b { color: red; }
65	    /// a {
66	    ///   & > b { color: red; }
67	    /// }
68	    /// ```
69	    ///
70	    /// ```css
71	    /// a:hover { color: red; }
72	    /// a { color: red; }
73	    /// ```
74	    ///
75	    /// ```css
76	    /// a b {
77	    ///     color: red;
78	    /// }
79	    /// /* This selector is overwritten by the one above it, but this is not an error because the rule only evaluates it as a compound selector */
80	    /// :where(a) :is(b) {
81	    ///     color: blue;
82	    /// }
83	    /// ```
84	    ///
85	    pub NoDescendingSpecificity {
86	        version: "1.9.3",
87	        name: "noDescendingSpecificity",
88	        language: "css",
89	        recommended: true,
90	        severity: Severity::Warning,
91	        sources: &[RuleSource::Stylelint("no-descending-specificity").same()],
92	    }
93	}
