96	pub struct DescendingSelector {
97	    high: (TextRange, Specificity),
98	    low: (TextRange, Specificity),
99	}
100	/// find tail selector
101	/// ```css
102	/// a b:hover {
103	///   ^^^^^^^
104	/// }
105	/// ```
106	fn find_tail_selector_str(selector: &AnyCssSelector) -> Option<String> {
107	    match selector {
108	        AnyCssSelector::CssCompoundSelector(s) => {
109	            let simple = s
110	                .simple_selector()
111	                .map_or(String::new(), |s| s.syntax().text_trimmed().to_string());
112	            let sub = s.sub_selectors().syntax().text_trimmed().to_string();
113	
114	            let last_selector = [simple, sub].join("");
115	            Some(last_selector)
116	        }
117	        AnyCssSelector::CssComplexSelector(s) => {
118	            s.right().as_ref().ok().and_then(find_tail_selector_str)
119	        }
120	        _ => None,
121	    }
122	}
123	
124	/// This function traverses the CSS rules starting from the given rule and checks for selectors that have the same tail selector.
125	/// For each selector, it compares its specificity with the previously encountered specificity of the same tail selector.
126	/// If a lower specificity selector is found after a higher specificity selector with the same tail selector, it records this as a descending selector.
127	fn find_descending_selector(
128	    root: &AnyCssRoot,
129	    rule: &CssSemanticRule,
130	    model: &SemanticModel,
131	    visited_rules: &mut FxHashSet<RuleId>,
132	    visited_selectors: &mut FxHashMap<String, (TextRange, Specificity)>,
133	    descending_selectors: &mut Vec<DescendingSelector>,
134	) {
135	    if !visited_rules.insert(rule.id()) {
136	        return;
137	    }
138	
139	    for selector in rule.selectors() {
140	        let Some(casted_selector) = AnyCssSelector::cast(selector.node(root).syntax().clone())
141	        else {
142	            continue;
143	        };
144	        let Some(tail_selector_str) = find_tail_selector_str(&casted_selector) else {
145	            continue;
146	        };
147	
148	        if let Some((last_text_range, last_specificity)) = visited_selectors.get(&tail_selector_str)
149	        {
150	            if last_specificity > &selector.specificity() {
151	                descending_selectors.push(DescendingSelector {
152	                    high: (*last_text_range, *last_specificity),
153	                    low: (selector.range(root), selector.specificity()),
154	                });
155	            }
156	        } else {
157	            visited_selectors.insert(
158	                tail_selector_str,
159	                (selector.range(root), selector.specificity()),
160	            );
161	        }
162	    }
163	
164	    for child_id in rule.child_ids() {
165	        if let Some(child_rule) = model.get_rule_by_id(child_id) {
166	            find_descending_selector(
167	                root,
168	                child_rule,
169	                model,
170	                visited_rules,
171	                visited_selectors,
172	                descending_selectors,
173	            );
174	        }
175	    }
176	}
177	
178	impl Rule for NoDescendingSpecificity {
179	    type Query = Semantic<AnyCssRoot>;
180	    type State = DescendingSelector;
181	    type Signals = Box<[Self::State]>;
182	    type Options = NoDescendingSpecificityOptions;
183	
184	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
185	        let model = ctx.model();
186	        let root = ctx.root();
187	        let mut visited_rules = FxHashSet::default();
188	        let mut visited_selectors = FxHashMap::default();
189	        let mut descending_selectors = Vec::new();
190	        for rule in model.rules() {
191	            find_descending_selector(
192	                &root,
193	                rule,
194	                model,
195	                &mut visited_rules,
196	                &mut visited_selectors,
197	                &mut descending_selectors,
198	            );
199	        }
200	        descending_selectors.into_boxed_slice()
201	    }
202	
