#[derive(Debug)]
pub struct RuleState {
    /// The range of the offending selector.
    range: TextRange,
    /// The number of class selectors found in the offending selector.
    found: u16,
}

/// Counts the class selectors contained in `node` (including itself).
///
/// Returns `None` when the selector contains an SCSS interpolation, meaning it
/// should not be flagged at all.
fn count_class_selectors(node: &CssSyntaxNode) -> Option<u16> {
    let mut count: u16 = 0;
    for descendant in node.descendants() {
        match descendant.kind() {
            CssSyntaxKind::SCSS_INTERPOLATION => return None,
            CssSyntaxKind::CSS_CLASS_SELECTOR => count = count.saturating_add(1),
            _ => {}
        }
    }
    Some(count)
}

impl Rule for NoExcessiveSelectorClasses {
    type Query = Ast<AnyCssQualifiedRule>;
    type State = RuleState;
    type Signals = Box<[Self::State]>;
    type Options = NoExcessiveSelectorClassesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let Some(max_classes) = ctx.options().max_classes else {
            return Box::default();
        };

        let mut signals = Vec::new();
        for selector in ctx.query().selectors() {
            if let Some(found) = count_class_selectors(&selector) {
                if found > max_classes {
                    signals.push(RuleState {
                        range: selector.text_trimmed_range(),
                        found,
                    });
                }
            }
        }

        signals.into_boxed_slice()
    }

    fn diagnostic(ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let max_classes = ctx.options().max_classes?;
        let message = if max_classes == 1 {
            markup! {
                "Expected this selector to have no more than "{max_classes.to_string()}" class selector, but found "{state.found.to_string()}"."
            }
        } else {
            markup! {
                "Expected this selector to have no more than "{max_classes.to_string()}" class selectors, but found "{state.found.to_string()}"."
            }
        };

        Some(
            RuleDiagnostic::new(rule_category!(), state.range, message)
                .note(markup! {
                    "Selectors with too many chained classes are harder to read, override, and reuse."
                })
                .note(markup! {
                    "Reduce the number of class selectors in this selector, or split it into simpler selectors."
                }),
        )
    }
}

impl AnyCssQualifiedRule {
    /// Returns the syntax node of each top-level selector in the rule's prelude.
    fn selectors(&self) -> Vec<CssSyntaxNode> {
        match self {
            AnyCssQualifiedRule::CssQualifiedRule(rule) => rule
                .prelude()
                .iter()
                .filter_map(|selector| selector.ok())
                .map(|selector| selector.into_syntax())
                .collect(),
            AnyCssQualifiedRule::CssNestedQualifiedRule(rule) => rule
                .prelude()
                .iter()
                .filter_map(|selector| selector.ok())
                .map(|selector| selector.into_syntax())
                .collect(),
        }
    }
}
