use biome_analyze::{
    AnalysisFilter, AnalyzerConfiguration, AnalyzerOptions, ControlFlow, Never, RuleFilter,
    RuleKey,
};
use biome_css_analyze::{CssAnalyzerServices, analyze};
use biome_css_parser::{CssParserOptions, parse_css};
use biome_css_syntax::CssFileSource;
use biome_rule_options::no_excessive_selector_classes::NoExcessiveSelectorClassesOptions;
use std::slice;

fn run(source: &str, max_classes: Option<u16>, scss: bool) -> usize {
    let file_source = if scss {
        CssFileSource::scss()
    } else {
        CssFileSource::css()
    };
    let parsed = parse_css(source, file_source, CssParserOptions::default());

    let mut rules = AnalyzerRules::default();
    rules.push_rule(
        RuleKey::new("nursery", "noExcessiveSelectorClasses"),
        RuleOptions::new(NoExcessiveSelectorClassesOptions { max_classes }, None),
    );
    let options = AnalyzerOptions::default()
        .with_configuration(AnalyzerConfiguration::default().with_rules(rules));

    let rule_filter = RuleFilter::Rule("nursery", "noExcessiveSelectorClasses");
    let semantic_model = biome_css_semantic::semantic_model(&parsed.tree());
    let services = CssAnalyzerServices::default()
        .with_file_source(file_source)
        .with_semantic_model(&semantic_model);

    let mut count = 0usize;
    analyze(
        &parsed.tree(),
        AnalysisFilter {
            enabled_rules: Some(slice::from_ref(&rule_filter)),
            ..AnalysisFilter::default()
        },
        &options,
        services,
        &[],
        |signal| {
            if let Some(diag) = signal.diagnostic() {
                count += 1;
                let msg = format!("{:?}", diag);
                eprintln!("  diag: {}", &msg[..msg.len().min(160)]);
            }
            ControlFlow::<Never>::Continue(())
        },
    );
    count
}

fn check(name: &str, source: &str, max: Option<u16>, scss: bool, expected: usize) {
    eprintln!("CASE {name} (max={max:?}): source={source:?}");
    let got = run(source, max, scss);
    let status = if got == expected { "OK" } else { "FAIL" };
    eprintln!("  => got {got} diagnostics, expected {expected} [{status}]\n");
}

fn main() {
    // maxClasses not configured -> no diagnostics ever
    check("none", ".a.b.c.d {}", None, false, 0);
    // max=1 -> 2+ classes triggers
    check("max1 single ok", ".a {}", Some(1), false, 0);
    check("max1 same element", ".a.b {}", Some(1), false, 1);
    check("max1 descendant", ".a .b {}", Some(1), false, 1);
    check("max1 with element", "div.a .b {}", Some(1), false, 1);
    // max=0 -> 1+ classes triggers
    check("max0 one class", ".a {}", Some(0), false, 1);
    check("max0 element only", "div {}", Some(0), false, 0);
    // max=2 -> 3+ triggers
    check("max2 two classes", ".a.b {}", Some(2), false, 0);
    check("max2 three classes", ".a.b.c {}", Some(2), false, 1);
    // pseudo-class function args counted
    check("max1 :not inner", ".a:not(.b) {}", Some(1), false, 1);
    check("outer2 not2 = 4", ".a.b:not(.c.d) {}", Some(3), false, 1);
    check("is counted", ".a:is(.b, .c) {}", Some(2), false, 1);
    check("nth-of counted", "li:nth-child(2n of .a, .b) {}", Some(1), false, 1);
    // comma list independent
    check("comma independent", ".a.b, .c {}", Some(1), false, 1);
    check("comma both", ".a.b, .c.d {}", Some(1), false, 2);
    // nesting independent
    check("nesting independent", ".a.b { & .c {} }", Some(1), false, 1);
    check("nesting parent ok", ".a { & .b.c {} }", Some(1), false, 1);
    // scss interpolation skipped
    check("scss interpolation", ".a.b.#{$c} {}", Some(1), true, 0);
    check("scss interp mixed", ".foo-#{$x}.bar {}", Some(1), true, 0);
}
